        // ─── دوال بحث شاملة للأدوات / Comprehensive tooling lookups ───
        // (AR) ملاحظة: بعض الأسماء الأساسية مشتركة بين فضاءات مختلفة
        //      (مثل «أرسل» في HttpClient وAsyncAdvanced). يعيد هذا البحث
        //      أوّل تطابق بترتيب language-truth/builtins/_index.yaml؛ لتعداد
        //      كل التطابقات كرِّر على ALL_BUILTINS مباشرة (المرحلة اللاحقة).
        // (EN) Note: a few canonical names are shared across namespaces.
        //      This returns the FIRST match in _index.yaml order; iterate
        //      ALL_BUILTINS directly to enumerate every match.
        inline const BuiltinMeta* findBuiltinMeta(std::string_view name)
        {
            for (const auto& b : ALL_BUILTINS)
                if (b.canonicalName == name) return &b;
            return nullptr;
        }

        inline bool isKnownBuiltin(std::string_view name)
        {
            return findBuiltinMeta(name) != nullptr;
        }


